import React, { useState, useEffect } from "react";
import "./Seo.css";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faFileLines, faClosedCaptioning, faSearch, faImage } from "@fortawesome/free-solid-svg-icons";

function SEO({ videoThumbnail }) {
  const location = useLocation(); // Get the location object
  const seoData = location.state; // Extract the state passed via navigate()

  const [activeTab, setActiveTab] = useState("Keywords");
  const [currentSeoData, setCurrentSeoData] = useState("");

  // Debugging: Log the received seoData for verification
  useEffect(() => {
    console.log("Received seoData:", seoData);
  }, [seoData]);

  // Update the displayed SEO data dynamically based on the active tab
  useEffect(() => {
    if (seoData) {
      switch (activeTab) {
        case "Keywords":
          setCurrentSeoData(
            seoData.keywords && seoData.keywords.length > 0
              ? seoData.keywords.join(", ")
              : "No keywords available."
          );
          break;
        case "Description":
          setCurrentSeoData(seoData.description || "No description available.");
          break;
        case "Title":
          setCurrentSeoData(seoData.title || "No title available.");
          break;
        case "Tags":
          setCurrentSeoData(
            seoData.tags && seoData.tags.length > 0
              ? seoData.tags.join(", ")
              : "No tags available."
          );
          break;
        default:
          setCurrentSeoData("No data available for this section.");
      }
    } else {
      setCurrentSeoData("No SEO data provided.");
    }
  }, [activeTab, seoData]);

  return (
    <div className="seo-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content Section */}
      <main className="main-content">
        {/* Navigation to Clipper */}
        <button className="clipper-btn">Go to Clipper</button>

        {/* Clip Section */}
        <div className="clip-section">
          {/* Image Preview */}
          <div className="image-preview">
            <img
              src={videoThumbnail || "https://via.placeholder.com/300x300"}
              alt="Video Thumbnail"
              className="preview-image"
            />
          </div>

          {/* Clip Customization */}
          <div className="customize-clip">
            {/* Menu for Options */}
            <div className="menu">
              <button
                className={activeTab === "Keywords" ? "active" : ""}
                onClick={() => setActiveTab("Keywords")}
              >
                <FontAwesomeIcon icon={faFileLines} /> Keywords
              </button>
              <button
                className={activeTab === "Description" ? "active" : ""}
                onClick={() => setActiveTab("Description")}
              >
                <FontAwesomeIcon icon={faClosedCaptioning} /> Description
              </button>
              <button
                className={activeTab === "Title" ? "active" : ""}
                onClick={() => setActiveTab("Title")}
              >
                <FontAwesomeIcon icon={faSearch} /> Title
              </button>
              <button
                className={activeTab === "Tags" ? "active" : ""}
                onClick={() => setActiveTab("Tags")}
              >
                <FontAwesomeIcon icon={faImage} /> Tags
              </button>
            </div>

            {/* SEO Data Display */}
            <div className="seo-data-box">
              <p>{currentSeoData}</p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default SEO;
